package org.duofold.live.wallpaperlayer;import android.graphics.*;import android.accessibilityservice.AccessibilityService;import java.util.concurrent.Executor;public class HomeCaptureSource{public static int captures,windowId;public static HomeCaptureSource last;public final Bitmap wallpaper=new Bitmap(1248,1972);public final Rect crop=new Rect(0,0,1248,1972);public final int width=1248,height=1972,rotation=0;public final String physical="cover";public static HomeCaptureSource current(){return last=new HomeCaptureSource();}public static class Window{public final int id;public final Rect bounds=new Rect(0,0,1248,1972);Window(int i){id=i;}}public Window window(){return new Window(windowId);}public void capture(Window w,Executor e,AccessibilityService.TakeScreenshotCallback c){captures++;e.execute(()->c.onSuccess(new AccessibilityService.ScreenshotResult()));}}
